from pybricks.hubs import PrimeHub
from pybricks.parameters import Color, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
right_motor = Motor(Port.A, Direction.CLOCKWISE)
left_motor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
sweeper = Motor(Port.C, Direction.COUNTERCLOCKWISE)
gate = Motor(Port.D, Direction.CLOCKWISE)
left_colour_sensor = ColorSensor(Port.F)
right__colour_sensor = ColorSensor(Port.E)
drive_base = DriveBase(left_motor, right_motor, 62.4, 202.5)

async def subtask(colour):
    while not await left_colour_sensor.color() == colour:
        await wait(0)
        left_motor.run(100)
    left_motor.brake()

async def subtask2(colour):
    while not await right__colour_sensor.color() == colour:
        await wait(0)
        right_motor.run(100)
    right_motor.brake()

async def line_squaring(colour):
    await wait(0)
    await multitask(
        subtask(colour),
        subtask2(colour),
    )

async def main():
    drive_base.settings(straight_speed=200)
    drive_base.settings(straight_acceleration=750)
    drive_base.settings(turn_rate=150)
    drive_base.settings(turn_acceleration=750)
    await line_squaring(Color.NONE)


run_task(main())